class RoomMemInfoReq:
    """Opcode 5060: eERC_ROOM_MEM_INFO_REQ (request).

    Sent when a Find party row is clicked: GetRoomMemberInfoREQ(
    m_vecRoomList[iChildIdx].m_nRoomUID ). Live: ffffff7f + i64 room uid.
    """
